; Demônios: the game for the Casio PV-1000 (32 KB ROM, no mapper).
;
; Engine that interprets the script generated by src/tools/rom.py (src/rom/generated/script.asm).
; Build with `make rom`.
;
; Current stage: text, pages, options, state (humanity, bond, items, flags,
; counters), conditions and effects, darkness, "on zero", forgotten items, inventory,
; compressed images, compressed text (BPE), pause, title and ending. No password: the game
; is short, and the endings seen stay in RAM while the console is on.
;
; Controls: up/down arrows choose, Fire 1 confirms and turns the page, Fire 2
; opens the inventory, Start pauses.
;
; ROM map (the same as the gallery, see docs/technical.md):
;   0x0000-0x003F  header and interrupt vector (0x0038)
;   0x0040-0x0BFF  bank 0: font and interface (tiles 0x02-0x5F)
;   0x0C00-0x1BFF  bank 0: image patterns
;   0x1C00-0x1FFF  compressed images (part)
;   0x2040-0x2BFF  bank 1: the same font
;   0x2C00-0x3BFF  bank 1: image patterns
;   0x3C00-0x3FFF  compressed images (part)
;   0x4000-0x7FFF  engine, script and the rest of the images
;
; Screen: the TV only shows columns 2-29; the text goes from column 2 to 29 (28 columns).

MAP:        equ 0xB800
PCG:        equ 0xBC00          ; patterns of tiles 0xE0-0xFF

; interface tiles (src/tools/font.py)
SPACE:      equ 0x20
T_SEPARATOR: equ 0x11
T_BAR:      equ 0x12
T_BAR_R:    equ 0x13
T_EMPTY:    equ 0x14
T_CURSOR:   equ 0x15
T_MORE:     equ 0x16
NEW_LINE:   equ 0x1E
NEW_PAGE:   equ 0x1F

; buttons (bits of PRESSED)
B_UP:       equ 0
B_DOWN:     equ 1
B_F1:       equ 2
B_F2:       equ 3
B_START:    equ 4

; modes
M_TITLE:    equ 0
M_SCENE:    equ 1
M_END:      equ 2
M_INV:      equ 3
M_PAUSE:    equ 4

; ------------------------------------------------------------------ RAM (0xBB00-0xBBFF)
; Fixed addresses: the automated test (src/tools/driver) reads the state from here.
RAM:        equ 0xBB00
SCENE:      equ RAM+0x00
HUM:        equ RAM+0x01
BOND:       equ RAM+0x02
ITEMS:      equ RAM+0x03
FLAGS:      equ RAM+0x04
PROTECT:    equ RAM+0x05
SEEN:       equ RAM+0x06        ; endings seen (carries across playthroughs)
DARK:       equ RAM+0x07
COUNTERS:   equ RAM+0x08        ; 8 counters
BUTTONS:    equ RAM+0x18
PREVIOUS:   equ RAM+0x19
PRESSED:    equ RAM+0x1A
BEEP:       equ RAM+0x1B
MODE:       equ RAM+0x1C
CURSOR:     equ RAM+0x1D
N_OPS:      equ RAM+0x1E        ; visible options
OPT_ROWS:   equ RAM+0x1F
TEXT_TOP:   equ RAM+0x20
TEXT_H:     equ RAM+0x21
SEP_ROW:    equ RAM+0x22
LAST_PAGE:  equ RAM+0x23        ; 1 = the page shown is the last one
PAGE_PTR:   equ RAM+0x24
NEXT_PTR:   equ RAM+0x26
TEXT_PTR:   equ RAM+0x28
OPS_PTR:    equ RAM+0x2A        ; start of the options in the scene record
OPS:        equ RAM+0x2C        ; up to 4 pointers to the visible options
INFO:       equ RAM+0x34        ; copy of the first 4 bytes of the scene
ROUTE:      equ RAM+0x35
IMG:        equ RAM+0x36
TARGET:     equ RAM+0x37
ROW:        equ RAM+0x39
N_ROWS:     equ RAM+0x3A
PREV_SHOWN: equ RAM+0x3B
TMP:        equ RAM+0x3C        ; 2 bytes
SPECIAL:    equ RAM+0x3E        ; 0 normal options, 1 "continue", 2 "end", 3 no exit,
                                ; 4 "About the author" screen (the option is "back")
SEEN_RAM:   equ RAM+0x40        ; "ENDINGS SEEN: k/n" assembled here (up to 0x53)
DEGRADE:    equ RAM+0x54        ; degrading text: 0 normal, 1 first sentence only, 2 fragments
COL:        equ RAM+0x55        ; column of the next word (degraded text)
LINE_PTR:   equ RAM+0x56        ; position in the compressed text (2 bytes)
SENTENCE_END: equ RAM+0x58      ; 1 = the first sentence is over (level 1)
LZ_REST:    equ RAM+0x60        ; decompression (src/rom/decompress.asm)
LZ_REST16:  equ RAM+0x61
LZ_POS:     equ RAM+0x63
LZ_DOFF:    equ RAM+0x65
LZ_SOFF:    equ RAM+0x66
LZ_NBITS:   equ RAM+0x67
LZ_FLAGS:   equ RAM+0x68
LZ_LEN:     equ RAM+0x69
BUSY:       equ RAM+0x6B        ; 1 while the game is working (the test waits for zero)
NEW_FRAME:  equ RAM+0x6C        ; set by the interrupt when a new frame starts
SHOWN_IMG:  equ RAM+0x6A        ; image on screen: index, 0xFF none,
                                ; 0xFE the screen was erased
SCRATCH:    equ RAM+0x70        ; 40 bytes: center() expands the text here to measure it
MUS:        equ RAM+0x98        ; music: per channel (2 and 3), pointer, frames, start
                                ; (5 bytes each; pointer 0 = channel stopped)
WORD:       equ RAM+0xA2        ; one word of the degraded text (up to 0xBF)
; the stack grows down from 0xBBFF; nothing goes past 0xBBBF

; ------------------------------------------------------------------ header
        org 0x0000
        di
        ld sp,0xBC00        ; stack at the end of the work RAM (0xBC00 onwards is the PCG)
        jp start

; ------------------------------------------------------------------ interrupt (IM 1)
; The frame is waited for with the interrupt, as the games do, and not by polling port
; 0xFC: the MiSTer core clears its flag on the read, and loses a frame when the flag is set
; in the same clock as the read. Here port 0xFC is read only in the interrupt, long after
; the flag is set. The MiSTer core interrupts on several lines per frame; only the one with
; bit 0 of port 0xFC set is the new frame, and it returns with interrupts off: on the real
; console it stays pending until port 0xFD is written, which the matrix read right after
; does. The wait enables them again. 0x0038 is in tile 0x01, which the font leaves unused for this.
        ds 0x0038-$
        jp irq

; ------------------------------------------------------------------ bank 0
        ds 0x0040-$
        include "generated/font_b0.asm"
        ds 0x0C00-$
        include "generated/bank0.asm"
        ds 0x1C00-$         ; tiles >= 0xE0 never come from here: room for data
        include "generated/img_1c00.asm"

; ------------------------------------------------------------------ bank 1
        ds 0x2040-$
        include "generated/font_b1.asm"
        ds 0x2C00-$
        include "generated/bank1.asm"
        ds 0x3C00-$
        include "generated/img_3c00.asm"

; ------------------------------------------------------------------ engine
        ds 0x4000-$
start:
        xor a
        out (0xFF),a        ; black border, bank 0
        ld a,0xB8
        out (0xFE),a        ; map at 0xB800, PCG at 0xBC00 (real console)
        ld a,63
        out (0xF8),a        ; sound muted
        out (0xF9),a
        out (0xFA),a
        ld a,0x02
        out (0xFB),a        ; sound on
        ld a,0x01
        out (0xFC),a        ; new frame flag and interrupt

        ld hl,RAM           ; clears the work RAM (except the stack)
        ld (hl),0
        ld de,RAM+1
        ld bc,0xBF
        ldir
        ; (the stack is still empty here)
        im 1
        call title_screen

main_loop:
        xor a
        ld (BUSY),a
ml_wait:
        ei
        halt                ; waits for a new frame
        ld a,(NEW_FRAME)
        or a
        jr z,ml_wait
        xor a
        ld (NEW_FRAME),a
        inc a
        ld (BUSY),a
        call music_frame
        ld a,(BEEP)         ; the beep lasts a few frames
        or a
        jr z,ml_buttons
        dec a
        ld (BEEP),a
        jr nz,ml_buttons
        ld a,63
        out (0xF8),a
ml_buttons:
        call read_buttons
        ld a,(PRESSED)
        or a
        jr z,main_loop
        ld b,a
        ld a,(MODE)
        cp M_SCENE
        jr nz,ml_not_scene
        call scene_button
        jr main_loop
ml_not_scene:
        cp M_END
        jr nz,ml_not_end
        call end_button
        jr main_loop
ml_not_end:
        cp M_INV
        jr nz,ml_not_inv
        call inv_button
        jr main_loop
ml_not_inv:
        cp M_PAUSE
        jr nz,ml_not_pause
        call pause_button
        jr main_loop
ml_not_pause:
        call title_button
        jr main_loop

; The interrupt: marks a new frame when bit 0 of port 0xFC is set (see the vector at 0x0038).
irq:    push af
        in a,(0xFC)
        and 1
        jr z,irq_other
        ld (NEW_FRAME),a    ; a new frame: back with interrupts off
        pop af
        reti
irq_other:
        pop af
        ei
        reti

; ------------------------------------------------------------------ input
; Reads player 1's matrix and leaves in PRESSED only what was just pressed.
;   row 0 (FD=1): bit 1 Start      row 1 (FD=2): bit 0 down
;   row 2 (FD=4): bit 1 up         row 3 (FD=8): bit 1 Fire 1, bit 0 Fire 2
read_buttons:
        ld c,0
        ld a,4
        call matrix_row
        bit 1,a
        jr z,rb_1
        set B_UP,c
rb_1:   ld a,2
        call matrix_row
        bit 0,a
        jr z,rb_2
        set B_DOWN,c
rb_2:   ld a,8
        call matrix_row
        bit 1,a
        jr z,rb_3
        set B_F1,c
rb_3:   bit 0,a
        jr z,rb_4
        set B_F2,c
rb_4:   ld a,1
        call matrix_row
        bit 1,a
        jr z,rb_5
        set B_START,c
rb_5:   ld a,(PREVIOUS)
        cpl
        and c
        ld (PRESSED),a
        ld a,c
        ld (PREVIOUS),a
        ret

; selects matrix row A, waits for it to settle (~180 cycles, on the real console) and reads
matrix_row:
        out (0xFD),a
        ld b,12
mr_wait:
        djnz mr_wait
        in a,(0xFD)
        ret

; A = note (8739 Hz / (63 - A)), E = frames
beep:   out (0xF8),a
        ld a,e
        ld (BEEP),a
        ret

; ------------------------------------------------------------------ playthrough
new_game:
        call stop_music     ; the story plays in silence
        ld a,HUM_START
        ld (HUM),a
        ld a,BOND_START
        ld (BOND),a
        xor a
        ld (ITEMS),a
        ld (FLAGS),a
        ld (PROTECT),a
        ld hl,COUNTERS
        ld b,8
ng_counters:
        ld (hl),a
        inc hl
        djnz ng_counters
        ld a,START_SCENE
        ; falls through into enter_scene

; Enters scene A: applies the effects, picks the text and shows it.
enter_scene:
        ld (SCENE),a
        call scene_address
        ld de,INFO          ; info, route, image, target
        ld bc,4
        ldir
        call apply          ; on_enter
        push hl
        xor a               ; dark = marked dark, no light of its own and no lantern
        ld (DARK),a
        ld a,(INFO)
        bit 0,a
        jr z,en_lit
        bit 1,a
        jr nz,en_lit
        ld hl,cond_light
        call cond
        jr nz,en_lit
        ld a,1
        ld (DARK),a
        ld hl,cond_dark     ; the dark costs humanity while it holds
        call cond
        jr z,en_lit
        ld a,0xFF
        call change_hum
en_lit:
        pop hl
        ld b,(hl)           ; text variants: the first one that passes wins
        inc hl
        ld de,0
en_variant:
        ld a,b
        or a
        jr z,en_default
        push bc
        push de
        call cond
        pop de
        ld c,a
        ld a,d
        or e
        jr nz,en_skip       ; already chosen
        ld a,c
        or a
        jr z,en_skip
        call apply
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        jr en_next
en_skip:
        call skip_effect
        inc hl
        inc hl
en_next:
        pop bc
        dec b
        jr en_variant
en_default:
        ld a,d
        or e
        jr nz,en_had
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        jr en_text
en_had:
        inc hl
        inc hl
en_text:
        ld (TEXT_PTR),de
        ld (OPS_PTR),hl

        ld a,(INFO)         ; ending: goes into the memory
        bit 2,a
        jr z,en_forget
        ld a,(TARGET)
        call bit_n
        ld b,a
        ld a,(SEEN)
        or b
        ld (SEEN),a
en_forget:
        call forget

        ld a,(HUM)          ; humanity hit zero: goes to the route's ending
        or a
        jr nz,en_show
        ld a,(INFO)
        bit 2,a
        jr nz,en_show
        ld a,(ROUTE)
        ld e,a
        ld d,0
        ld hl,on_zero
        add hl,de
        ld a,(hl)
        cp 0xFF
        jr z,en_show
        ld b,a
        ld a,(SCENE)
        cp b
        jr z,en_show
        ld a,b
        jp enter_scene

en_show:
        ld a,M_SCENE
        ld (MODE),a
        ld a,52
        ld e,4
        call beep
        call build_view
        jp draw_scene

; HL = record of scene A
scene_address:
        ld l,a
        ld h,0
        add hl,hl
        ld de,tab_scenes
        add hl,de
        ld a,(hl)
        inc hl
        ld h,(hl)
        ld l,a
        ret

; Visible options and screen geometry.
build_view:
        xor a
        ld (N_OPS),a
        ld (CURSOR),a
        ld (SPECIAL),a
        ld a,(INFO)
        bit 2,a
        jr z,bv_not_ending
        ld a,2
        ld (SPECIAL),a
        jr bv_geometry
bv_not_ending:
        bit 3,a
        jr z,bv_options
        ld a,1
        ld (SPECIAL),a
        ld (N_OPS),a
        jr bv_geometry
bv_options:
        ld a,1
        ld (PREV_SHOWN),a
        ld hl,(OPS_PTR)
        ld b,(hl)
        inc hl
bv_loop:
        ld a,b
        or a
        jr z,bv_options_done
        push bc
        ld (TMP),hl
        ld a,(hl)
        inc hl
        or a
        jr z,bv_cond
        call skip_cond      ; "else": shows up if the previous one did not
        ld a,(PREV_SHOWN)
        xor 1
        jr bv_visible
bv_cond:
        call cond
bv_visible:
        ld (PREV_SHOWN),a
        or a
        jr z,bv_skip
        ld a,(N_OPS)
        cp 4
        jr nc,bv_skip
        push hl
        add a,a
        ld e,a
        ld d,0
        ld hl,OPS
        add hl,de
        ld de,(TMP)
        ld (hl),e
        inc hl
        ld (hl),d
        pop hl
        ld a,(N_OPS)
        inc a
        ld (N_OPS),a
bv_skip:
        call skip_effect
        inc hl              ; goto
        inc hl              ; text
        inc hl
        pop bc
        dec b
        jr bv_loop
bv_options_done:
        ld a,(N_OPS)
        or a
        jr nz,bv_geometry
        ld a,3              ; no visible option: script error
        ld (SPECIAL),a
        ld a,1
        ld (N_OPS),a
bv_geometry:
        ld a,(N_OPS)        ; option rows: at least 3
        cp 3
        jr nc,bv_rows
        ld a,3
bv_rows:
        ld (OPT_ROWS),a
        ld b,a
        ld a,23
        sub b
        ld (SEP_ROW),a
        ld c,a
        ld a,(INFO)
        bit 4,a
        ld a,1
        jr z,bv_top
        ld a,13
bv_top: ld (TEXT_TOP),a
        ld b,a
        ld a,c
        sub b
        ld (TEXT_H),a
        ld hl,(TEXT_PTR)
        ld (PAGE_PTR),hl
        ret

; ------------------------------------------------------------------ conditions and effects
; Evaluates the condition at HL. Returns A = 1 (holds) or 0, with Z to match, and HL past it.
cond:   ld c,1
co_loop:
        ld a,(hl)
        inc hl
        or a
        jr z,co_done
        ld b,(hl)           ; nearly all of them have 1 operand
        inc hl
        cp 1
        jr z,co_has
        cp 2
        jr z,co_has_not
        cp 3
        jr z,co_flag
        cp 4
        jr z,co_no_flag
        cp 5
        jr z,co_hum_min
        cp 6
        jr z,co_hum_max
        cp 7
        jr z,co_bond_min
        cp 8
        jr z,co_bond_max
        cp 11
        jr z,co_endings
        ld e,b              ; 9 and 10: counter k, value n
        ld d,0
        ld b,(hl)
        inc hl
        push hl
        ld hl,COUNTERS
        add hl,de
        ld e,(hl)           ; E = counter value
        pop hl
        cp 9
        ld a,e
        jr z,co_at_least
        jr co_at_most
co_has: ld a,(ITEMS)
co_all:
        and b
        cp b
        jr z,co_loop
        jr co_false
co_has_not:
        ld a,(ITEMS)
co_none:
        and b
        jr z,co_loop
        jr co_false
co_flag:
        ld a,(FLAGS)
        jr co_all
co_no_flag:
        ld a,(FLAGS)
        jr co_none
co_hum_min:
        ld a,(HUM)
        jr co_at_least
co_hum_max:
        ld a,(HUM)
        jr co_at_most
co_bond_min:
        ld a,(BOND)
        jr co_at_least
co_bond_max:
        ld a,(BOND)
        jr co_at_most
co_endings:
        ld a,(SEEN)
        push bc
        call count_bits
        pop bc
co_at_least:                ; holds if A >= B
        cp b
        jr nc,co_loop
        jr co_false
co_at_most:                 ; holds if A <= B
        cp b
        jr z,co_loop
        jr c,co_loop
co_false:
        ld c,0
        jp co_loop
co_done: ld a,c
        or a
        ret

; Applies the effect at HL; returns HL past it.
apply:
        ld a,(hl)
        inc hl
        or a
        ret z
        cp 8
        jr z,ap_protect
        ld b,(hl)
        inc hl
        cp 1
        jr z,ap_gain
        cp 2
        jr z,ap_lose
        cp 3
        jr z,ap_set_flag
        cp 4
        jr z,ap_clear_flag
        cp 5
        jr z,ap_bond
        cp 7
        jr z,ap_hum
        ld e,b              ; 6: add k d
        ld d,0
        ld b,(hl)
        inc hl
        push hl
        ld hl,COUNTERS
        add hl,de
        ld a,(hl)
        add a,b
        ld (hl),a
        pop hl
        jr apply
ap_protect:
        ld a,1
        ld (PROTECT),a
        jr apply
ap_gain:
        ld a,(ITEMS)
        or b
        ld (ITEMS),a
        jr apply
ap_lose:
        ld a,b
        cpl
        ld b,a
        ld a,(ITEMS)
        and b
        ld (ITEMS),a
        jr apply
ap_set_flag:
        ld a,(FLAGS)
        or b
        ld (FLAGS),a
        jr apply
ap_clear_flag:
        ld a,b
        cpl
        ld b,a
        ld a,(FLAGS)
        and b
        ld (FLAGS),a
        jr apply
ap_bond:
        ld a,(BOND)
        add a,b
        call clamp7
        ld (BOND),a
        jr apply
ap_hum:
        ld a,b
        push hl
        call change_hum
        pop hl
        jr apply

; Skips a condition / an effect at HL without evaluating it.
skip_cond:
        ld a,(hl)
        inc hl
        or a
        ret z
        inc hl
        cp 9
        jr z,sc_two
        cp 10
        jr nz,skip_cond
sc_two:
        inc hl
        jr skip_cond

skip_effect:
        ld a,(hl)
        inc hl
        or a
        ret z
        cp 8
        jr z,skip_effect
        inc hl
        cp 6
        jr nz,skip_effect
        inc hl
        jr skip_effect

; Adds A (signed) to humanity. "Protect" cancels the next loss.
change_hum:
        bit 7,a
        jr z,ch_add
        ld b,a
        ld a,(PROTECT)
        or a
        ld a,b
        jr z,ch_add
        xor a
        ld (PROTECT),a
        ret
ch_add:
        ld b,a
        ld a,(HUM)
        add a,b
        call clamp7
        ld (HUM),a
        ret

; A (signed) clamped to 0-7
clamp7:
        bit 7,a
        jr z,c7_pos
        xor a
        ret
c7_pos: cp 8
        ret c
        ld a,7
        ret

; Items that vanish from the inventory with low humanity.
forget:
        ld hl,tab_forget
fg_loop:
        ld a,(hl)
        or a
        ret z
        ld b,a
        inc hl
        ld c,(hl)           ; maximum humanity
        inc hl
        ld a,(HUM)
        ld d,a
        ld a,c
        cp d
        jr c,fg_loop        ; HUM > maximum: stays
        ld a,b
        cpl
        ld b,a
        ld a,(ITEMS)
        and b
        ld (ITEMS),a
        jr fg_loop

; A = number of bits set in A
count_bits:
        ld c,0
        ld b,8
cnt_loop:
        rrca
        jr nc,cnt_zero
        inc c
cnt_zero:
        djnz cnt_loop
        ld a,c
        ret

; A = 1 << A
bit_n:  ld b,a
        ld a,1
        inc b
bn_loop:
        dec b
        ret z
        add a,a
        jr bn_loop

; ------------------------------------------------------------------ buttons per mode
; B = PRESSED
scene_button:
        ld a,(SPECIAL)      ; the author screen has no inventory and no pause
        cp 4
        jr z,sb_pages
        bit B_F2,b
        jp nz,open_inventory
        bit B_START,b
        jp nz,open_pause
sb_pages:
        ld a,(LAST_PAGE)
        or a
        jr nz,sb_last
        bit B_F1,b          ; not the last page: Fire 1 turns it
        ret z
        ld hl,(NEXT_PTR)
        ld (PAGE_PTR),hl
        ld a,45
        ld e,2
        call beep
        jp draw_scene
sb_last:
        ld a,(SPECIAL)
        cp 2
        jr nz,sb_options
        bit B_F1,b          ; ending: Fire 1 goes to the end screen
        ret z
        jp end_screen
sb_options:
        ld a,(N_OPS)
        ld c,a
        bit B_UP,b
        jr z,sb_down
        ld a,(CURSOR)
        or a
        jr nz,sb_up
        ld a,c
sb_up:
        dec a
        jr sb_move
sb_down:
        bit B_DOWN,b
        jr z,sb_f1
        ld a,(CURSOR)
        inc a
        cp c
        jr c,sb_move
        xor a
sb_move:
        ld (CURSOR),a
        ld a,40
        ld e,2
        call beep
        jp draw_cursor
sb_f1:  bit B_F1,b
        ret z
        ld a,(SPECIAL)
        cp 1
        jr nz,sb_not_auto
        ld a,(TARGET)
        jp enter_scene
sb_not_auto:
        cp 3
        jp z,title_screen   ; no exit: back to the title
        cp 4
        jp z,title_screen   ; author screen: "back"
        ld a,(CURSOR)       ; the chosen option: applies the effect and goes
        add a,a
        ld e,a
        ld d,0
        ld hl,OPS
        add hl,de
        ld a,(hl)
        inc hl
        ld h,(hl)
        ld l,a
        inc hl              ; else
        call skip_cond
        call apply
        ld a,(hl)
        jp enter_scene

end_button:                 ; any button (Fire 1, Fire 2, Start) goes back to the title,
        ld a,(MUS)          ; but only after the ending's music is over
        ld hl,MUS+1
        or (hl)
        ld hl,MUS+5
        or (hl)
        inc hl
        or (hl)
        ret nz
        ld a,b
        and 0x1C
        ret z
        jp title_screen

inv_button:
        ld a,b
        and 0x0C            ; Fire 1 or Fire 2
        ret z
        ld a,M_SCENE
        ld (MODE),a
        jp draw_scene

title_button:
        ld a,b
        and 0x03            ; up or down: switches the option
        jr z,tb_f1
        ld a,(CURSOR)
        xor 1
        ld (CURSOR),a
        ld a,40
        ld e,2
        call beep
        ld a,20
        jp cursor2
tb_f1:  ld a,b
        and 0x14            ; Fire 1 or Start
        ret z
        ld a,(CURSOR)
        or a
        jp z,new_game
        ; falls through into about_author

; "About the author" screen: the portrait and the text in pages, like a scene with an
; image and a single option, "back".
about_author:
        ld a,M_SCENE
        ld (MODE),a
        ld a,0x10           ; has an image, is neither an ending nor dark
        ld (INFO),a
        ld a,IMG_AUTOR
        ld (IMG),a
        xor a
        ld (DARK),a
        ld (CURSOR),a
        ld a,4
        ld (SPECIAL),a
        ld a,1
        ld (N_OPS),a
        ld a,3
        ld (OPT_ROWS),a
        ld a,20
        ld (SEP_ROW),a
        ld a,13
        ld (TEXT_TOP),a
        ld a,7
        ld (TEXT_H),a
        ld hl,txt_about
        ld (TEXT_PTR),hl
        ld (PAGE_PTR),hl
        jp draw_scene

; ------------------------------------------------------------------ drawing
; HL = map address of row A, column C (preserves BC and DE)
address:
        push bc
        ld l,a
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        ld b,0
        add hl,bc
        ld bc,MAP
        add hl,bc
        pop bc
        ret

clear_screen:
        ld hl,MAP
        ld (hl),SPACE
        ld de,MAP+1
        ld bc,32*24-1
        ldir
        ret

; clears from row A to the end of the screen
clear_from:
        ld c,0
        call address
        ex de,hl            ; DE = start
        ld hl,MAP+32*24
        or a
        sbc hl,de
        ld b,h              ; BC = how many
        ld c,l
        ex de,hl
cf_loop:
        ld (hl),SPACE
        inc hl
        dec bc
        ld a,b
        or c
        jr nz,cf_loop
        ret

; writes the string DE (BPE-compressed, ends in 0) starting at HL; at the end, DE =
; past the last character written
print_str:
        ex de,hl            ; HL = string, DE = screen
ps_loop:
        ld a,(hl)
        inc hl
        or a
        ret z
        call expand
        jr ps_loop

; writes code A at DE and advances; codes >= FIRST_PAIR are BPE pairs,
; expanded recursively (table dic). Preserves HL; uses BC.
expand:
        cp FIRST_PAIR
        jr nc,ex_pair
        ld (de),a
        inc de
        ret
ex_pair: push hl
        sub FIRST_PAIR
        ld l,a
        ld h,0
        add hl,hl
        ld bc,dic
        add hl,bc
        ld a,(hl)
        inc hl
        push hl
        call expand
        pop hl
        ld a,(hl)
        call expand
        pop hl
        ret

; writes the string DE centered on the row stored in TMP
center:
        push de
        ld hl,SCRATCH       ; measures: expands the string into a scratch area in RAM
        call print_str
        ex de,hl
        ld de,SCRATCH
        or a
        sbc hl,de
        ld b,l              ; B = length
        pop de
        ld a,32
        sub b
        srl a
        ld c,a
        ld a,(TMP)
        call address
        jr print_str

; separator on row A, edge to edge
separator:
        ld c,0
        call address
        ld b,32
sep_loop:
        ld (hl),T_SEPARATOR
        inc hl
        djnz sep_loop
        ret

; humanity bar on the separator row: columns 22-28
hum_bar:
        ld a,(SEP_ROW)
        ld c,21
        call address
        ld (hl),SPACE
        inc hl
        ld a,(HUM)
        ld d,a
        ld e,T_BAR
        cp 3
        jr nc,hb_color
        ld e,T_BAR_R        ; humanity 2 or less: red
hb_color: ld b,7
        ld c,0
hb_loop:
        ld a,c
        cp d
        ld a,e
        jr c,hb_full
        ld a,T_EMPTY
hb_full:
        ld (hl),a
        inc hl
        inc c
        djnz hb_loop
        ret

; Redraws the scene. The image is only drawn again if it changed (same image across
; consecutive scenes, pages, inventory): unpacking takes about two frames.
draw_scene:
        ld a,(INFO)         ; B = the image this scene shows
        bit 4,a
        ld a,0xFF
        jr z,ds_key
        ld a,(IMG)
ds_key:
        ld b,a
        ld a,(SHOWN_IMG)
        cp b
        jr z,ds_same
        ld a,b
        ld (SHOWN_IMG),a
        call clear_screen
        ld a,(SHOWN_IMG)
        cp 0xFF
        jr z,ds_text
        call draw_image
        ld a,12
        call separator
        jr ds_text
ds_same:
        cp 0xFF
        jr nz,ds_below
        call clear_screen
        jr ds_text
ds_below:
        ld a,13             ; the image and the separator stay
        call clear_from
ds_text:
        call draw_text
        ld a,(LAST_PAGE)
        or a
        jr nz,ds_footer
        ld a,(TEXT_TOP)     ; "there is more": in the corner of the last text row
        ld b,a
        ld a,(TEXT_H)
        add a,b
        dec a
        ld c,29
        call address
        ld (hl),T_MORE
ds_footer:
        ld a,(SEP_ROW)
        call separator
        ld a,(SPECIAL)      ; the author screen has no humanity bar
        cp 4
        call nz,hum_bar
        ld a,(LAST_PAGE)
        or a
        ret z
        ; falls through into draw_options

draw_options:
        ld a,(SPECIAL)
        or a
        jr z,do_normal
        ld de,txt_continue
        cp 1
        jr z,do_single
        ld de,txt_end
        cp 2
        jr z,do_single
        ld de,txt_back
        cp 4
        jr z,do_single
        ld de,txt_no_exit
do_single: ld a,(SEP_ROW)
        inc a
        ld c,4
        call address
        call print_str
        jp draw_cursor
do_normal:
        xor a
do_loop:
        ld b,a
        ld a,(N_OPS)
        cp b
        jp z,draw_cursor
        push bc
        ld a,b              ; pointer of option B
        add a,a
        ld e,a
        ld d,0
        ld hl,OPS
        add hl,de
        ld a,(hl)
        inc hl
        ld h,(hl)
        ld l,a
        inc hl              ; else
        call skip_cond
        call skip_effect
        inc hl              ; goto
        ld e,(hl)
        inc hl
        ld d,(hl)
        pop bc
        push bc
        ld a,(SEP_ROW)
        inc a
        add a,b
        ld c,4
        call address
        call print_option
        pop bc
        ld a,b
        inc a
        jr do_loop

; cursor in column 2 of the option rows
draw_cursor:
        ld a,(LAST_PAGE)
        or a
        ret z
        ld a,(N_OPS)
        or a
        jr nz,dcu_n
        inc a               ; ending: one row ("END")
dcu_n:  ld b,a
        ld a,(SEP_ROW)
        inc a
        ld c,2
        call address
        ld a,(CURSOR)
        ld c,a
        ld de,32
        xor a
dcu_loop:
        ld (hl),SPACE
        cp c
        jr nz,dcu_next
        ld (hl),T_CURSOR
dcu_next:
        add hl,de
        inc a
        djnz dcu_loop
        ret

; Writes the page starting at PAGE_PTR; sets LAST_PAGE and stores NEXT_PTR. With low
; humanity, the text degrades (see dt_degraded).
draw_text:
        call calc_degrade
        or a
        jp nz,dt_degraded
        ld a,(TEXT_TOP)
        ld (ROW),a
        xor a
        ld (N_ROWS),a
        ld a,(ROW)
        ld c,2
        call address
        ex de,hl            ; DE = screen
        ld hl,(PAGE_PTR)
dt_loop:
        ld a,(hl)
        or a
        jr z,dt_done
        cp NEW_PAGE
        jr z,dt_page
        cp NEW_LINE
        jr z,dt_line
        inc hl
        call expand
        jr dt_loop
dt_line:
        inc hl
        ld a,(N_ROWS)
        inc a
        ld (N_ROWS),a
        ld b,a
        ld a,(TEXT_H)
        cp b
        jr z,dt_full
        ld a,(ROW)
        inc a
        ld (ROW),a
        push hl
        ld c,2
        call address
        ex de,hl
        pop hl
        jr dt_loop
dt_page:
        inc hl
dt_full:
        ld (NEXT_PTR),hl
        xor a
        ld (LAST_PAGE),a
        ret
dt_done:
        ld a,1
        ld (LAST_PAGE),a
        ret

; ------------------------------------------------------------------ degrading text
; With humanity 3-4 only the first sentence of each page shows; with 1-2, the text loses
; its punctuation and stopwords (table `stopwords`). Route C (the account is being
; written) and the author screen do not degrade. Since the text gets shorter, each page is
; rewrapped here, word by word (the ROM lines come wrapped for the full
; text).

; A = DEGRADE (0, 1 or 2), computed from humanity
calc_degrade:
        xor a
        ld (DEGRADE),a
        ld a,(SPECIAL)
        cp 4
        jr z,cd_done
        ld a,(ROUTE)
        cp 3
        jr z,cd_done
        ld a,(HUM)
        cp 5
        jr nc,cd_done
        ld b,1
        cp 3
        jr nc,cd_set
        inc b
cd_set: ld a,b
        ld (DEGRADE),a
cd_done: ld a,(DEGRADE)
        ret

dt_degraded:
        ld a,(TEXT_TOP)
        ld (ROW),a
        xor a
        ld (COL),a
        ld (SENTENCE_END),a
        ld hl,(PAGE_PTR)
dg_line:                    ; expands one original line into the scratch area
        ld de,SCRATCH
dg_exp: ld a,(hl)
        or a
        jr z,dg_line_end
        cp NEW_LINE
        jr z,dg_line_end
        cp NEW_PAGE
        jr z,dg_line_end
        inc hl
        call expand
        jr dg_exp
dg_line_end:
        xor a
        ld (de),a
        ld (LINE_PTR),hl
        call dg_words
        ld hl,(LINE_PTR)
        ld a,(SENTENCE_END)
        or a
        jr nz,dg_skip
        ld a,(hl)
        cp NEW_LINE
        jr nz,dg_block_end
        inc hl
        jr dg_line
dg_skip:                    ; the first sentence is over: skips to the end of the page
        ld a,(hl)
        or a
        jr z,dg_block_end
        cp NEW_PAGE
        jr z,dg_block_end
        inc hl
        jr dg_skip
dg_block_end:
        ld a,(hl)
        or a
        jr z,dg_last
        inc hl
        ld (NEXT_PTR),hl
        xor a
        ld (LAST_PAGE),a
        ret
dg_last:
        ld a,1
        ld (LAST_PAGE),a
        ret

; the words in the scratch area, already filtered, go to the screen
dg_words:
        ld hl,SCRATCH
dgw_loop:
        call next_word
        ret z
        push hl
        ld a,b
        or a
        jr z,dgw_next
        ld a,(DEGRADE)
        cp 2
        jr nz,dgw_emit
        push bc
        call is_stopword
        pop bc
        jr z,dgw_next
dgw_emit:
        push bc
        call emit_word
        pop bc
        ld a,(DEGRADE)
        cp 1
        jr nz,dgw_next
        ld a,c              ; level 1: the sentence ends in . ! ?
        cp '.'
        jr z,dgw_sentence
        cp '!'
        jr z,dgw_sentence
        cp '?'
        jr nz,dgw_next
dgw_sentence:
        ld a,1
        ld (SENTENCE_END),a
        pop hl
        ret
dgw_next:
        pop hl
        jr dgw_loop

; HL = position in the scratch area. Skips spaces and copies the next word to WORD
; (without the punctuation on level 2). Returns B = length, C = last original character,
; HL past it; Z if the text is over.
next_word:
        ld a,(hl)
        cp SPACE
        jr nz,nw_start
        inc hl
        jr next_word
nw_start:
        or a
        ret z
        ld de,WORD
        ld b,0
nw_copy:
        ld a,(hl)
        or a
        jr z,nw_done
        cp SPACE
        jr z,nw_done
        inc hl
        ld c,a
        ld a,(DEGRADE)
        cp 2
        ld a,c
        jr nz,nw_put
        call is_punctuation
        jr z,nw_copy
nw_put: ld (de),a
        inc de
        inc b
        jr nw_copy
nw_done: ld a,1
        or a
        ret

; Z if A is punctuation (vanishes on level 2)
is_punctuation:
        push hl
        push bc
        ld hl,punctuation
        ld b,punctuation_end-punctuation
ip_loop:
        cp (hl)
        jr z,ip_exit
        inc hl
        djnz ip_loop
ip_exit:
        pop bc
        pop hl
        ret
punctuation:
        db '.',',',';',':','!','?','"','(',')',0x18,0x0F,0x10   ; 0x18 —, 0x0F ¿, 0x10 ¡
punctuation_end:

; Z if WORD (B letters) is in the stopword table
is_stopword:
        ld hl,stopwords
isw_loop:
        ld a,(hl)
        or a
        jr z,isw_no
        cp b
        jr nz,isw_skip
        push hl
        inc hl
        ld de,WORD
        ld c,b
isw_cmp: ld a,(de)
        cp (hl)
        jr nz,isw_diff
        inc hl
        inc de
        dec c
        jr nz,isw_cmp
        pop hl
        xor a
        ret
isw_diff: pop hl
isw_skip:
        ld e,(hl)
        inc e
        ld d,0
        add hl,de
        jr isw_loop
isw_no: inc a               ; A was 0: NZ
        ret

; writes WORD (B letters) on row ROW, column COL, rewrapping; stops at the last
; row of the text area
emit_word:
        ld a,(COL)
        or a
        jr z,ew_row
        add a,b
        inc a
        cp 29
        jr c,ew_same
        ld a,(ROW)
        inc a
        ld (ROW),a
        xor a
        ld (COL),a
        jr ew_row
ew_same:
        ld a,(COL)          ; the space is already on screen (cleared)
        inc a
        ld (COL),a
ew_row:
        ld a,(TEXT_TOP)
        ld e,a
        ld a,(TEXT_H)
        add a,e
        ld e,a
        ld a,(ROW)
        cp e
        ret nc
        ld a,(COL)
        add a,2
        ld c,a
        ld a,(ROW)
        call address
        ex de,hl
        ld hl,WORD
        ld a,(COL)
        add a,b
        ld (COL),a
        ld c,b
        ld b,0
        ldir
        ret

; option: on level 2 it loses the punctuation and the stopwords, like the text
print_option:
        ld a,(DEGRADE)
        cp 2
        jp nz,print_str
        push hl
        ld hl,SCRATCH
        call print_str
        xor a
        ld (de),a
        pop de
        ld hl,SCRATCH
po_loop:
        push de
        call next_word
        pop de
        ret z
        ld a,b
        or a
        jr z,po_loop
        push hl
        push de
        push bc
        call is_stopword
        pop bc
        pop de
        pop hl
        jr z,po_loop
        push hl
        ld hl,WORD
        ld c,b
        ld b,0
        ldir
        pop hl
        inc de              ; a space
        jr po_loop

; Draws image IMG: switches the pattern bank, unpacks the PCG and the map. In the
; dark the image is the same (decision of 2026-10-18): the cost shows on the bar.
draw_image:
        ld a,(IMG)          ; HL = tab_img + IMG * 6
        ld l,a
        ld h,0
        add hl,hl
        ld d,h
        ld e,l
        add hl,hl
        add hl,de
        ld de,tab_img
        add hl,de
        ld a,(hl)
        out (0xFF),a        ; the image's bank (the font is in both)
        inc hl
        ld a,(hl)           ; number of PCG tiles
        inc hl
        ld e,(hl)
        inc hl
        ld d,(hl)           ; DE = map
        inc hl
        push de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ex de,hl            ; HL = PCG
        call pcg_unpack
        pop hl
        jp map_unpack

open_inventory:
        ld a,M_INV
        ld (MODE),a
        ld a,(TEXT_TOP)
        call clear_from
        ld a,(TEXT_TOP)
        ld c,2
        call address
        ld de,txt_inventory
        call print_str
        ld a,(TEXT_TOP)
        add a,2
        ld (ROW),a
        ld hl,tab_items
        ld a,(ITEMS)
        ld b,N_ITEMS
        or a
        jr nz,oi_loop
        ld a,(ROW)          ; nothing
        ld c,3
        call address
        ld de,txt_nothing
        call print_str
        jr oi_footer
oi_loop:
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld a,(ITEMS)
        ld c,a
        ld a,N_ITEMS
        sub b               ; A = item number
        push hl
        push bc
        push de
        call bit_n
        pop de
        pop bc
        and c
        jr z,oi_next
        push bc
        ld a,(ROW)
        ld c,3
        call address
        call print_str
        ld hl,ROW
        inc (hl)
        pop bc
oi_next:
        pop hl
        djnz oi_loop
oi_footer:
        ld a,(SEP_ROW)
        call separator
        call hum_bar
        ld a,(SEP_ROW)
        inc a
        ld c,2
        call address
        ld de,txt_closes
        jp print_str

end_screen:
        ld a,M_END
        ld (MODE),a
        ld a,0xFE           ; the screen is about to be erased: the next scene redraws the image
        ld (SHOWN_IMG),a
        xor a
        ld (CURSOR),a
        call clear_screen
        ld a,IMG_FIM        ; the same image for every ending (10 tile rows)
        ld (IMG),a
        call draw_image
        ld a,11
        call separator
        ld de,txt_end_big
        ld a,12
        ld (TMP),a
        call center
        ld a,(TARGET)       ; the ending's name (the type is not shown: the music is what changes)
        add a,a
        ld e,a
        ld d,0
        ld hl,tab_endings
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ld a,14
        ld (TMP),a
        call center
        ld a,17
        call print_endings_seen
        ld a,(TARGET)       ; music for the ending's type
        ld e,a
        ld d,0
        ld hl,tab_ending_type
        add hl,de
        ld a,(hl)
        add a,a
        ld e,a
        ld hl,tab_mus_end
        add hl,de
        ld a,(hl)
        inc hl
        ld h,(hl)
        ld l,a
        call play_music
        ret                 ; no options: any button goes back to the title

; two options on rows A and A+1 (texts DE and HL, column 4) with the cursor at CURSOR
two_options:
        push af
        push hl
        push af
        ld c,4
        call address
        call print_str
        pop af
        inc a
        ld c,4
        call address
        pop de
        call print_str
        pop af
        ; falls through into cursor2

; cursor in column 2 of rows A and A+1, according to CURSOR (0 or 1)
cursor2:
        ld c,2
        call address
        ld a,(CURSOR)
        ld b,T_CURSOR
        ld c,SPACE
        or a
        jr z,c2_put
        ld b,SPACE
        ld c,T_CURSOR
c2_put: ld (hl),b
        ld de,32
        add hl,de
        ld (hl),c
        ret

; writes "ENDINGS SEEN: k/n" centered on row A (assembled in RAM)
print_endings_seen:
        ld (TMP),a
        ld hl,txt_seen
        ld de,SEEN_RAM
        ld bc,TXT_SEEN_LEN
        ldir
        ld a,(SEEN)
        call count_bits
        add a,0x30
        ld (SEEN_RAM+TXT_SEEN_K),a
        ld de,SEEN_RAM
        jp center

title_screen:
        ld hl,mus_title
        call play_music
        ld a,M_TITLE
        ld (MODE),a
        ld a,0xFE
        ld (SHOWN_IMG),a
        call clear_screen
        ld a,IMG_ABERTURA   ; the opening image takes up 10 tile rows
        ld (IMG),a
        call draw_image
        ld a,11
        call separator
        ld de,txt_title
        ld a,12
        ld (TMP),a
        call center
        ld hl,subtitle      ; subtitle, line by line, starting at row 14
        ld a,14
        ld (ROW),a
ts_sub: ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld a,d
        or e
        jr z,ts_sub_done
        ld a,(ROW)
        ld (TMP),a
        inc a
        ld (ROW),a
        push hl
        call center
        pop hl
        jr ts_sub
ts_sub_done:
        ld a,(SEEN)
        or a
        jr z,ts_options
        ld a,17
        call print_endings_seen
ts_options:
        xor a
        ld (CURSOR),a
        ld a,20
        ld de,txt_start
        ld hl,txt_about_menu
        call two_options
        ld de,txt_credits
        ld a,23
        ld (TMP),a
        jp center

; ------------------------------------------------------------------ pause
open_pause:
        ld a,M_PAUSE
        ld (MODE),a
        xor a
        ld (CURSOR),a
        ld a,(TEXT_TOP)
        call clear_from
        ld a,(TEXT_TOP)
        ld c,2
        call address
        ld de,txt_pause
        call print_str
        ld a,(SEP_ROW)
        call separator
        ld a,(SEP_ROW)
        inc a
        ld de,txt_continue
        ld hl,txt_back_to_title
        jp two_options

pause_button:
        ld a,b
        and 0x03            ; up or down
        jr z,pb_f1
        ld a,(CURSOR)
        xor 1
        ld (CURSOR),a
        ld a,40
        ld e,2
        call beep
        ld a,(SEP_ROW)
        inc a
        jp cursor2
pb_f1:  ld a,b
        and 0x14            ; Fire 1 or Start
        ret z
        ld a,(CURSOR)
        or a
        jp nz,title_screen
        ld a,M_SCENE
        ld (MODE),a
        jp draw_scene

; ------------------------------------------------------------------ music
; HL = music (dw channel 2, dw channel 3; format in src/tools/music.py)
play_music:
        ld de,MUS
        call pm_channel
        ld de,MUS+5
pm_channel:
        ld a,(hl)           ; channel pointer
        inc hl
        ld (de),a
        inc de
        ld b,a
        ld a,(hl)
        inc hl
        ld (de),a
        inc de
        ld c,a
        ld a,1              ; plays the first note on the next frame
        ld (de),a
        inc de
        ld a,b              ; start, for the loop
        ld (de),a
        inc de
        ld a,c
        ld (de),a
        ret

stop_music:
        xor a
        ld (MUS),a
        ld (MUS+1),a
        ld (MUS+5),a
        ld (MUS+6),a
        ld a,63
        out (0xF9),a
        out (0xFA),a
        ret

; one frame of music: channel 2 (port F9) and channel 3 (port FA)
music_frame:
        ld hl,MUS
        ld c,0xF9
        call mf_channel
        ld hl,MUS+5
        ld c,0xFA
mf_channel:
        ld e,(hl)           ; DE = pointer
        inc hl
        ld d,(hl)
        inc hl
        ld a,d
        or e
        ret z               ; channel stopped
        dec (hl)            ; frames of the current note
        ret nz
mf_read: ld a,(de)
        cp 0xFF
        jr z,mf_done
        cp 0xFE
        jr nz,mf_note
        inc hl              ; back to the start
        ld e,(hl)
        inc hl
        ld d,(hl)
        dec hl
        dec hl
        jr mf_read
mf_note:
        out (c),a
        inc de
        ld a,(de)
        inc de
        ld (hl),a           ; frames
        dec hl
        ld (hl),d
        dec hl
        ld (hl),e
        ret
mf_done:
        ld a,63
        out (c),a
        dec hl              ; stops the channel
        ld (hl),0
        dec hl
        ld (hl),0
        ret

        include "generated/script.asm"
        include "generated/music.asm"
        include "decompress.asm"
        include "generated/img_table.asm"
        include "generated/img_rest.asm"

        ds 0x8000-$
